int get_bluetooth_socket_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer)
{
    struct sockaddr_hci hci_addr;

    if (!sock->sk || !sock->sk->sk_dev || !is_bluetooth_device_valid(sock->sk->sk_dev)) {
        return -EBADFD;
    }

    lock_sock(sock->sk);
    hci_addr.hci_family = AF_BLUETOOTH;
    if (peer) {
        hci_addr.hci_dev = sock->sk->sk_peer_dev;
        hci_addr.hci_channel = sock->sk->sk_peer_channel;
    } else {
        hci_addr.hci_dev = sock->sk->sk_dev->dev_num;
        hci_addr.hci_channel = sock->sk->sk_channel;
    }
    unlock_sock(sock->sk);

    memcpy(addr, &hci_addr, sizeof(hci_addr));
    *addr_len = sizeof(struct sockaddr_hci);

    return 0;
}

int get_socket_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer) {
    if (!sock || !addr || !addr_len) {
        return -EBADFD;
    }

    if (!bt_dev_valid(sock->sk)) {
        return -EBADFD;
    }

    lock_sock(sock->sk);

    struct sockaddr_hci *hci_addr = (struct sockaddr_hci *)addr;
    hci_addr->hci_family = AF_BLUETOOTH;
    hci_addr->hci_dev = sock->sk->sk_hci_dev;
    hci_addr->hci_channel = sock->sk->sk_hci_channel;

    *addr_len = sizeof(struct sockaddr_hci);

    release_sock(sock->sk);

    return 0;
}

int get_bt_sock_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer) {
    if (!sock || !addr || !addr_len) {
        return -EBADFD;
    }

    struct sock *sk = sock->sk;
    if (!sk || sk->sk_family != AF_BLUETOOTH) {
        return -EBADFD;
    }

    lock_sock(sk);

    struct sockaddr_hci *haddr = (struct sockaddr_hci *)addr;
    haddr->sa_family = AF_BLUETOOTH;

    if (peer) {
        memcpy(&haddr->hci_bdaddr, &bt_sk(sk)->src, sizeof(haddr->hci_bdaddr));
        haddr->hci_dev = bt_sk(sk)->src_dev;
    } else {
        memcpy(&haddr->hci_bdaddr, &bt_sk(sk)->dst, sizeof(haddr->hci_bdaddr));
        haddr->hci_dev = bt_sk(sk)->dst_dev;
    }

    *addr_len = sizeof(struct sockaddr_hci);
    release_sock(sk);

    return 0;
}

int get_bt_sock_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer) {
    if (!sock || !sock->sk || !bt_sk(sock->sk))
        return -EBADFD;

    struct sock *sk = sock->sk;
    struct hci_dev *hdev = bt_sk(sk)->hdev;
    struct sockaddr_hci *hci_addr;

    if (!hdev || !addr || !addr_len)
        return -EBADFD;

    hci_addr = (struct sockaddr_hci *)addr;
    hci_addr->hci_family = AF_BLUETOOTH;

    if (peer) {
        memcpy(&hci_addr->hci_dev, &hdev->bdaddr, sizeof(bdaddr_t));
        hci_addr->hci_channel = hdev->type;
    } else {
        memcpy(&hci_addr->hci_dev, &hdev->bdaddr, sizeof(bdaddr_t));
        hci_addr->hci_channel = hdev->type;
    }

    *addr_len = sizeof(*hci_addr);
    return 0;
}

int bluetooth_getsockname(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer)
{
    struct sockaddr_hci hciaddr;

    if (!sock || !addr || !addr_len)
        return -EBADFD;

    if (peer) {
        if (sock->sk->sk_state != BT_CONNECTED)
            return -EBADFD;
    }

    hciaddr.hci_family = AF_BLUETOOTH;
    hciaddr.hci_dev = sock->sk->sk_dev;
    hciaddr.hci_channel = sock->sk->sk_channel;

    if (copy_to_user(addr, &hciaddr, sizeof(hciaddr)))
        return -EBADFD;

    *addr_len = sizeof(hciaddr);

    return 0;
}
